/// <summary>
/// Finds record
/// </summary>
/// <param name = "_inventTable">InventTable</param>
/// <param name = "_update">true or false</param>
/// <returns>Record</returns>
static public NDXItemValidityDateEconomicBatchSize find(InventTable _inventTable, boolean _update = false)
{
    NDXItemValidityDateEconomicBatchSize lNDXItemValidityDateEconomicBatchSize;

    if(_inventTable)
    {
        lNDXItemValidityDateEconomicBatchSize.selectForUpdate(_update);

        select lNDXItemValidityDateEconomicBatchSize
            where lNDXItemValidityDateEconomicBatchSize.RefRecId_InventTable == _inventTable.RecId;
    }

    return lNDXItemValidityDateEconomicBatchSize;
}

/// <summary>
/// Checks if validity check is available
/// </summary>
/// <param name = "_inventTable">InventTable</param>
/// <returns>true or false</returns>
static public boolean hasValidityCheck(InventTable _inventTable)
{
    return NDXItemValidityDateEconomicBatchSize::find(_inventTable).RecId > 0;
}

display UnitIDBase dispItemUnit()
{
    UnitIDBase unitId = '';
    InventTable lInventTable;
    InventTableModule lInventTableModule;

    lInventTable = InventTable::findRecId(this.RefRecId_InventTable);
    lInventTableModule = InventTableModule::find(lInventTable.ItemId, ModuleInventPurchSales::Sales);

    if(lInventTableModule)
    {
        unitId = lInventTableModule.UnitId;
    }

    return unitId;
}

private void writeLog(NDXItemValidityDateEconomicBatchSize _orig,  NDXItemValidityDateEconomicBatchSize _current)
{
    NDXMultipleS_Log   multipleS_Log;

    if(!_current)
    {
        multipleS_Log.RefRecIdInventTable = _orig.RefRecId_InventTable;
    }
    else
    {
        multipleS_Log.RefRecIdInventTable = _current.RefRecId_InventTable;
    }

    if (_orig.DateFrom != _current.DateFrom)
    {
        multipleS_Log.ValidityCheckType = NDXValidityCheckType::DateFrom;
        multipleS_Log.RangeValue        = Date2StrUsr(_current.DateFrom, DateFlags::FormatAll);

        if (!_orig.DateFrom)            // Neuanlage
        {
            multipleS_Log.ChangeType        = NDXChangeType::New;
        }
        else if (!_current.DateFrom)        // Löschung
        {
            multipleS_Log.RangeValue        = Date2StrUsr(_orig.DateFrom, DateFlags::FormatAll);
            multipleS_Log.ChangeType        = NDXChangeType::Delete;
        }
        else                            // Änderung
        {
            multipleS_Log.ChangeType        = NDXChangeType::Update;
        }
        multipleS_Log.insert();
    }

    if (_orig.DateTo != _current.DateTo)
    {
        multipleS_Log.ValidityCheckType = NDXValidityCheckType::DateTo;
        multipleS_Log.RangeValue        = Date2StrUsr(_current.DateTo, DateFlags::FormatAll);

        if (!_orig.DateTo)              // Neuanlage
        {
            multipleS_Log.ChangeType        = NDXChangeType::New;
        }
        else if (!_current.DateTo)          // Löschung
        {
            multipleS_Log.RangeValue        = Date2StrUsr(_orig.DateTo, DateFlags::FormatAll);
            multipleS_Log.ChangeType        = NDXChangeType::Delete;
        }
        else                            // Änderung
        {
            multipleS_Log.ChangeType        = NDXChangeType::Update;
        }
        multipleS_Log.insert();
    }

    if (_orig.EconomicBatchSize != _current.EconomicBatchSize)
    {
        multipleS_Log.ValidityCheckType = NDXValidityCheckType::EconomicBatchSize;
        multipleS_Log.RangeValue        = num2str(_current.EconomicBatchSize, 12, 2, 2, 1);

        if (!_orig.EconomicBatchSize)           // Neuanlage
        {
            multipleS_Log.ChangeType        = NDXChangeType::New;
        }
        else if (!_current.EconomicBatchSize)       // Löschung
        {
            multipleS_Log.RangeValue        = num2str(_orig.EconomicBatchSize, 12, 2, 2, 1);
            multipleS_Log.ChangeType        = NDXChangeType::Delete;
        }
        else                                    // Änderung
        {
            multipleS_Log.ChangeType        = NDXChangeType::Update;
        }
        multipleS_Log.insert();
    }

}

public void insert()
{
    NDXItemValidityDateEconomicBatchSize orig = this.orig();
    super();
    this.writeLog(orig, this);
}

public void update()
{
    NDXItemValidityDateEconomicBatchSize orig = this.orig();

    if(!this.DateFrom && !this.DateTo && !this.EconomicBatchSize)
    {
        this.doDelete();
    }
    else
    {
        super();
    }
    this.writeLog(orig, this);
}

public void delete()
{
    NDXItemValidityDateEconomicBatchSize orig = this.orig();
    super();
    this.writeLog(orig, null);
}
